changeSet.sql:
CREATE OR REPLACE TRIGGER trg_incidencia_snapshot_ro
BEFORE UPDATE OF room_name_snapshot, office_name_snapshot, category_name_snapshot ON incidencia
FOR EACH ROW
BEGIN
    IF NVL(:NEW.room_name_snapshot, '@@NULL@@')     <> NVL(:OLD.room_name_snapshot, '@@NULL@@')
    OR NVL(:NEW.office_name_snapshot, '@@NULL@@')   <> NVL(:OLD.office_name_snapshot, '@@NULL@@')
    OR NVL(:NEW.category_name_snapshot, '@@NULL@@') <> NVL(:OLD.category_name_snapshot, '@@NULL@@') THEN
        RAISE_APPLICATION_ERROR(-20010, 'El registro histórico no admite modificaciones');
    END IF;
END;

CREATE OR REPLACE TRIGGER trg_incidencia_clasificacion
BEFORE INSERT OR UPDATE OF room_id, category_id ON incidencia
FOR EACH ROW
DECLARE
    l_room_name     cat_sala.room_name%TYPE;
    l_room_active   cat_sala.is_active%TYPE;
    l_office_name   cat_oficina.office_name%TYPE;
    l_cat_name      cat_categoria_incidencia.category_name%TYPE;
    l_cat_active    cat_categoria_incidencia.is_active%TYPE;
BEGIN
    BEGIN
        SELECT s.room_name, s.is_active, o.office_name
          INTO l_room_name, l_room_active, l_office_name
          FROM cat_sala s
          JOIN cat_oficina o ON o.office_id = s.office_id
         WHERE s.room_id = :NEW.room_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20011, 'La sala seleccionada no existe o ya no esta disponible');
    END;

    BEGIN
        SELECT c.category_name, c.is_active
          INTO l_cat_name, l_cat_active
          FROM cat_categoria_incidencia c
         WHERE c.category_id = :NEW.category_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20012, 'La categoría seleccionada no es válida');
    END;

    IF l_room_active = 'N' THEN
        RAISE_APPLICATION_ERROR(-20011, 'La sala seleccionada no existe o ya no esta disponible');
    END IF;

    IF l_cat_active = 'N' THEN
        RAISE_APPLICATION_ERROR(-20012, 'La categoría seleccionada no es válida');
    END IF;

    IF INSERTING THEN
        :NEW.room_name_snapshot     := NVL(:NEW.room_name_snapshot, l_room_name);
        :NEW.office_name_snapshot   := NVL(:NEW.office_name_snapshot, l_office_name);
        :NEW.category_name_snapshot := NVL(:NEW.category_name_snapshot, l_cat_name);
    END IF;
END;

DECLARE
    v_admin       NUMBER;
    v_empleado    NUMBER;
    v_office      NUMBER;
    v_room        NUMBER;
    v_cat_ok      NUMBER;
    v_cat_ko      NUMBER;
    v_inc         NUMBER;
    v_filas_antes NUMBER;
    v_filas_ahora NUMBER;
    v_sqlcode     NUMBER;
    v_room_snap   incidencia.room_name_snapshot%TYPE;
    v_office_snap incidencia.office_name_snapshot%TYPE;
    v_cat_snap    incidencia.category_name_snapshot%TYPE;
    v_status      incidencia.status%TYPE;
    v_version     NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_active VARCHAR2) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, p_active);

        -- Garantiza el estado de actividad que el oraculo necesita aunque la fila ya existiese.
        UPDATE cat_categoria_incidencia SET is_active = p_active WHERE category_code = p_code;
    END sembrar_categoria;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('MOBILIARIO', 'Mobiliario oraculo', 901, 'Y');
    sembrar_categoria('LIMPIEZA', 'Limpieza oraculo inactiva', 902, 'N');

    SELECT category_id INTO v_cat_ok FROM cat_categoria_incidencia WHERE category_code = 'MOBILIARIO';
    SELECT category_id INTO v_cat_ko FROM cat_categoria_incidencia WHERE category_code = 'LIMPIEZA';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA53' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA53', 'Oficina Oraculo TSK-053', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA53';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Clasificacion Admin', 'oraculo.tsk053.clas.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Clasificacion Empleado', 'oraculo.tsk053.clas.empleado@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_empleado;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA53' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA53', 'Sala Oraculo', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA53';

    SELECT COUNT(*) INTO v_filas_antes FROM incidencia;

    -- Intento A: categoria INEXISTENTE. Debe fallar (ORA-20012 del trigger, u ORA-02291 de la FK).
    BEGIN
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9053-000001', v_room, v_cat_ok + 100000,
                     'El proyector de la sala no enciende desde esta manana', v_empleado);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20930, 'ORACULO AC-CLAS-01: el alta con category_id inexistente deberia fallar y no fallo');
    END IF;

    -- Intento B: categoria EXISTENTE pero INACTIVA. La FK la aceptaria; el trigger la rechaza.
    BEGIN
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9053-000001', v_room, v_cat_ko,
                     'El proyector de la sala no enciende desde esta manana', v_empleado);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20012 THEN
        RAISE_APPLICATION_ERROR(-20931, 'ORACULO REQ-100: el alta con category_id inactivo devolvio ' || v_sqlcode || ' en lugar de ORA-20012');
    END IF;

    -- Intento C: sala INEXISTENTE con categoria valida.
    BEGIN
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9053-000001', v_room + 100000, v_cat_ok,
                     'El proyector de la sala no enciende desde esta manana', v_empleado);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20932, 'ORACULO AC-CLAS-01: el alta con room_id inexistente deberia fallar y no fallo');
    END IF;

    SELECT COUNT(*) INTO v_filas_ahora FROM incidencia;
    IF v_filas_ahora <> v_filas_antes THEN
        RAISE_APPLICATION_ERROR(-20933, 'ORACULO AC-CLAS-01: un alta rechazada ha dejado filas escritas en incidencia');
    END IF;

    -- Alta VALIDA sin informar los *_snapshot: los sella el motor desde el catalogo (REQ-150).
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
         VALUES ('INC-9053-000002', v_room, v_cat_ok,
                 'El proyector de la sala no enciende desde esta manana', v_empleado)
      RETURNING incident_id INTO v_inc;

    SELECT room_name_snapshot, office_name_snapshot, category_name_snapshot, status, version
      INTO v_room_snap, v_office_snap, v_cat_snap, v_status, v_version
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_room_snap <> 'Sala Oraculo'
       OR v_office_snap <> 'Oficina Oraculo TSK-053'
       OR v_cat_snap <> 'Mobiliario oraculo'
       OR v_status <> 'ABIERTA'
       OR v_version <> 0 THEN
        RAISE_APPLICATION_ERROR(-20934, 'ORACULO REQ-150: el alta valida no ha sellado la denominacion vigente ni el estado inicial');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin    NUMBER;
    v_empleado NUMBER;
    v_office   NUMBER;
    v_room     NUMBER;
    v_cat      NUMBER;
    v_inc      NUMBER;
    v_sqlcode  NUMBER;
    v_salas    NUMBER;
    v_cats     NUMBER;
    v_users    NUMBER;
    v_incs     NUMBER;
    v_room_ref NUMBER;
    v_cat_ref  NUMBER;
    v_rep_ref  NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_active VARCHAR2) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, p_active);

        UPDATE cat_categoria_incidencia SET is_active = p_active WHERE category_code = p_code;
    END sembrar_categoria;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('MOBILIARIO', 'Mobiliario oraculo', 901, 'Y');

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'MOBILIARIO';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA53' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA53', 'Oficina Oraculo TSK-053', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA53';

    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Borrado Admin', 'oraculo.tsk053.fk.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Borrado Empleado', 'oraculo.tsk053.fk.empleado@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_empleado;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA53' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA53', 'Sala Oraculo', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA53';

    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
         VALUES ('INC-9053-000010', v_room, v_cat,
                 'La silla de la sala esta rota y no se puede utilizar', v_empleado)
      RETURNING incident_id INTO v_inc;

    -- 1) La sala referenciada no se puede borrar: fk_incidencia_room no declara ON DELETE.
    BEGIN
        DELETE FROM cat_sala WHERE room_id = v_room;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2292 THEN
        RAISE_APPLICATION_ERROR(-20940, 'ORACULO REQ-102: el borrado de una sala referenciada devolvio ' || v_sqlcode || ' en lugar de ORA-02292');
    END IF;

    -- 2) Lo mismo con la categoria: fk_incidencia_category tampoco declara ON DELETE.
    BEGIN
        DELETE FROM cat_categoria_incidencia WHERE category_id = v_cat;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2292 THEN
        RAISE_APPLICATION_ERROR(-20941, 'ORACULO REQ-102: el borrado de una categoria referenciada devolvio ' || v_sqlcode || ' en lugar de ORA-02292');
    END IF;

    -- 3) Y con el reportante: fk_incidencia_reported_by no declara ON DELETE (REQ-087 / AC-TRZ-02).
    BEGIN
        DELETE FROM usuario WHERE user_id = v_empleado;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2292 THEN
        RAISE_APPLICATION_ERROR(-20942, 'ORACULO AC-TRZ-02: el borrado fisico del reportante devolvio ' || v_sqlcode || ' en lugar de ORA-02292');
    END IF;

    SELECT COUNT(*) INTO v_salas FROM cat_sala WHERE room_id = v_room;
    SELECT COUNT(*) INTO v_cats  FROM cat_categoria_incidencia WHERE category_id = v_cat;
    SELECT COUNT(*) INTO v_users FROM usuario WHERE user_id = v_empleado;
    SELECT COUNT(*) INTO v_incs  FROM incidencia WHERE incident_id = v_inc;

    IF v_salas <> 1 OR v_cats <> 1 OR v_users <> 1 OR v_incs <> 1 THEN
        RAISE_APPLICATION_ERROR(-20943, 'ORACULO AC-TRZ-02: la incidencia ha perdido su clasificacion o su atribucion tras los borrados rechazados');
    END IF;

    SELECT room_id, category_id, reported_by
      INTO v_room_ref, v_cat_ref, v_rep_ref
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_room_ref IS NULL OR v_room_ref <> v_room
       OR v_cat_ref IS NULL OR v_cat_ref <> v_cat
       OR v_rep_ref IS NULL OR v_rep_ref <> v_empleado THEN
        RAISE_APPLICATION_ERROR(-20943, 'ORACULO AC-TRZ-02: la incidencia ha perdido su clasificacion o su atribucion tras los borrados rechazados');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin        NUMBER;
    v_empleado     NUMBER;
    v_office       NUMBER;
    v_room         NUMBER;
    v_cat          NUMBER;
    v_inc          NUMBER;
    v_sqlcode      NUMBER;
    v_version      NUMBER;
    v_antes        VARCHAR2(4000);
    v_despues      VARCHAR2(4000);
    v_room_snap    incidencia.room_name_snapshot%TYPE;
    v_office_snap  incidencia.office_name_snapshot%TYPE;
    v_cat_snap     incidencia.category_name_snapshot%TYPE;
    v_room_ahora   incidencia.room_name_snapshot%TYPE;
    v_office_ahora incidencia.office_name_snapshot%TYPE;
    v_cat_ahora    incidencia.category_name_snapshot%TYPE;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_active VARCHAR2) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, p_active);

        -- Garantiza el estado de actividad que el oraculo necesita aunque la fila ya existiese.
        UPDATE cat_categoria_incidencia SET is_active = p_active WHERE category_code = p_code;
    END sembrar_categoria;

    FUNCTION instantanea(p_id NUMBER) RETURN VARCHAR2 IS
        v_txt VARCHAR2(4000);
    BEGIN
        SELECT incident_id || '|' || reference_code || '|' || room_id || '|' || category_id || '|' ||
               room_name_snapshot || '|' || office_name_snapshot || '|' || category_name_snapshot || '|' ||
               description || '|' || status || '|' || reported_by || '|' ||
               TO_CHAR(created_at, 'YYYY-MM-DD HH24:MI:SS.FF6') || '|' ||
               NVL(TO_CHAR(updated_at, 'YYYY-MM-DD HH24:MI:SS.FF6'), '~') || '|' ||
               version
          INTO v_txt
          FROM incidencia
         WHERE incident_id = p_id;
        RETURN v_txt;
    END instantanea;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('AUDIOVISUAL', 'Audiovisual oraculo', 903, 'Y');

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'AUDIOVISUAL';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA53C' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA53C', 'Oficina Oraculo Inmutable', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA53C';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Snapshot Admin', 'oraculo.tsk053.snap.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Snapshot Empleado', 'oraculo.tsk053.snap.empleado@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_empleado;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA53C' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA53C', 'Sala Oraculo Inmutable', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA53C';

    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
         VALUES ('INC-9053-000070', v_room, v_cat,
                 'La pantalla de la sala parpadea durante las reuniones', v_empleado)
      RETURNING incident_id INTO v_inc;

    SELECT room_name_snapshot, office_name_snapshot, category_name_snapshot
      INTO v_room_snap, v_office_snap, v_cat_snap
      FROM incidencia
     WHERE incident_id = v_inc;

    v_antes := instantanea(v_inc);

    -- Intento A: manipular la denominacion historica de la sala.
    BEGIN
        UPDATE incidencia SET room_name_snapshot = 'Sala Manipulada' WHERE incident_id = v_inc;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20010 THEN
        RAISE_APPLICATION_ERROR(-20950, 'ORACULO AC-RET-10: el UPDATE de room_name_snapshot devolvio ' || v_sqlcode || ' en lugar de ORA-20010');
    END IF;

    -- Intento B: manipular la denominacion historica de la oficina.
    BEGIN
        UPDATE incidencia SET office_name_snapshot = 'Oficina Manipulada' WHERE incident_id = v_inc;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20010 THEN
        RAISE_APPLICATION_ERROR(-20951, 'ORACULO AC-RET-10: el UPDATE de office_name_snapshot devolvio ' || v_sqlcode || ' en lugar de ORA-20010');
    END IF;

    -- Intento C: manipular la denominacion historica de la categoria.
    BEGIN
        UPDATE incidencia SET category_name_snapshot = 'Categoria Manipulada' WHERE incident_id = v_inc;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20010 THEN
        RAISE_APPLICATION_ERROR(-20952, 'ORACULO AC-RET-10: el UPDATE de category_name_snapshot devolvio ' || v_sqlcode || ' en lugar de ORA-20010');
    END IF;

    -- La proteccion es quirurgica: un UPDATE de OTRAS columnas tiene que pasar sin error.
    BEGIN
        UPDATE incidencia
           SET status = 'ABIERTA',
               updated_at = SYS_EXTRACT_UTC(SYSTIMESTAMP),
               version = version + 1
         WHERE incident_id = v_inc;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> 0 THEN
        RAISE_APPLICATION_ERROR(-20953, 'ORACULO AC-RET-10: el trigger de snapshots ha bloqueado un UPDATE legitimo de otras columnas');
    END IF;

    SELECT room_name_snapshot, office_name_snapshot, category_name_snapshot, version
      INTO v_room_ahora, v_office_ahora, v_cat_ahora, v_version
      FROM incidencia
     WHERE incident_id = v_inc;

    v_despues := instantanea(v_inc);

    IF v_room_ahora <> v_room_snap
       OR v_office_ahora <> v_office_snap
       OR v_cat_ahora <> v_cat_snap THEN
        RAISE_APPLICATION_ERROR(-20954, 'ORACULO AC-RET-10: alguna denominacion historica ha cambiado pese a los UPDATE rechazados' || SUBSTR(' [antes=' || v_antes || '] [despues=' || v_despues || ']', 1, 1800));
    END IF;

    IF v_version <> 1 THEN
        RAISE_APPLICATION_ERROR(-20955, 'ORACULO AC-RET-10: el UPDATE legitimo de version no se ha aplicado');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin     NUMBER;
    v_empleado  NUMBER;
    v_office    NUMBER;
    v_room      NUMBER;
    v_cat       NUMBER;
    v_inc       NUMBER;
    v_snapshot  incidencia.room_name_snapshot%TYPE;
    v_vigente   cat_sala.room_name%TYPE;
    v_detalle   VARCHAR2(400);
    v_cat_snap  incidencia.category_name_snapshot%TYPE;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_active VARCHAR2) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, p_active);

        -- Garantiza el estado de actividad que el oraculo necesita aunque la fila ya existiese.
        UPDATE cat_categoria_incidencia SET is_active = p_active WHERE category_code = p_code;
    END sembrar_categoria;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('CLIMATIZACION', 'Climatizacion oraculo', 904, 'Y');

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA53D' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA53D', 'Oficina Oraculo Retencion', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA53D';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Renombrado Admin', 'oraculo.tsk053.ren.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Renombrado Empleado', 'oraculo.tsk053.ren.empleado@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_empleado;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA53D' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA53D', 'Sala 2', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA53D';

    -- Alta SIN informar los *_snapshot: los sella el motor con la denominacion vigente.
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
         VALUES ('INC-9053-000080', v_room, v_cat,
                 'El aire acondicionado de la sala no deja de gotear', v_empleado)
      RETURNING incident_id INTO v_inc;

    SELECT room_name_snapshot INTO v_snapshot FROM incidencia WHERE incident_id = v_inc;
    IF v_snapshot <> 'Sala 2' THEN
        RAISE_APPLICATION_ERROR(-20960, 'ORACULO AC-RET-09: el alta no ha sellado la denominacion vigente de la sala');
    END IF;

    -- Renombrado LEGITIMO del catalogo: en cat_sala solo room_code es inmutable.
    UPDATE cat_sala
       SET room_name = 'Sala Norte',
           updated_at = SYS_EXTRACT_UTC(SYSTIMESTAMP),
           updated_by = v_admin
     WHERE room_id = v_room;

    -- El mismo JOIN que hace la pantalla de detalle: historico de la incidencia + vigente del catalogo.
    SELECT i.room_name_snapshot, s.room_name
      INTO v_snapshot, v_vigente
      FROM incidencia i
      JOIN cat_sala s ON s.room_id = i.room_id
     WHERE i.incident_id = v_inc;

    IF v_snapshot <> 'Sala 2' THEN
        RAISE_APPLICATION_ERROR(-20961, 'ORACULO AC-RET-09: el renombrado de la sala ha reescrito el snapshot historico de la incidencia');
    END IF;

    IF v_vigente <> 'Sala Norte' THEN
        RAISE_APPLICATION_ERROR(-20962, 'ORACULO AC-RET-09: el renombrado de la sala no se ha aplicado al catalogo');
    END IF;

    v_detalle := v_vigente || ' (en el momento del alta: ' || v_snapshot || ')';
    IF v_detalle <> 'Sala Norte (en el momento del alta: Sala 2)' THEN
        RAISE_APPLICATION_ERROR(-20963, 'ORACULO AC-RET-09: el detalle no puede componer la denominacion vigente mas la historica, resultado: ' || v_detalle);
    END IF;

    -- REQ-102: desactivar la categoria DESPUES del alta no deja la incidencia sin clasificacion legible.
    UPDATE cat_categoria_incidencia SET is_active = 'N' WHERE category_id = v_cat;

    SELECT category_name_snapshot INTO v_cat_snap FROM incidencia WHERE incident_id = v_inc;
    IF v_cat_snap IS NULL THEN
        RAISE_APPLICATION_ERROR(-20964, 'ORACULO AC-RET-09: la clasificacion deja de ser legible tras desactivar la categoria');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin    NUMBER;
    v_sesion   NUMBER;
    v_ajeno    NUMBER;
    v_office   NUMBER;
    v_room     NUMBER;
    v_cat      NUMBER;
    v_total    NUMBER;
    v_propias  NUMBER;
    v_ajenas   NUMBER;
    v_primera  NUMBER;
    v_maxima   NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_active VARCHAR2) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, p_active);

        -- Garantiza el estado de actividad que el oraculo necesita aunque la fila ya existiese.
        UPDATE cat_categoria_incidencia SET is_active = p_active WHERE category_code = p_code;
    END sembrar_categoria;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('OTROS', 'Otros oraculo', 905, 'Y');

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'OTROS';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA53E' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA53E', 'Oficina Oraculo Alcance', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA53E';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Alcance Admin', 'oraculo.tsk053.seg.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Alcance Sesion', 'oraculo.tsk053.seg.sesion@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_sesion;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Alcance Ajeno', 'oraculo.tsk053.seg.ajeno@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_ajeno;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA53E' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA53E', 'Sala Oraculo Alcance', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA53E';

    -- Tres incidencias del usuario de la sesion.
    FOR i IN 1..3 LOOP
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9053-1' || LPAD(i, 5, '0'), v_room, v_cat,
                     'Incidencia propia del usuario de la sesion numero ' || i, v_sesion);
    END LOOP;

    -- Diez incidencias de un reportante ajeno.
    FOR i IN 1..10 LOOP
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9053-2' || LPAD(i, 5, '0'), v_room, v_cat,
                     'Incidencia ajena de otro reportante numero ' || i, v_ajeno);
    END LOOP;

    SELECT COUNT(*) INTO v_total FROM incidencia WHERE reported_by IN (v_sesion, v_ajeno);
    IF v_total <> 13 THEN
        RAISE_APPLICATION_ERROR(-20970, 'ORACULO AC-SEG-01: el escenario deberia tener 13 incidencias y tiene ' || v_total);
    END IF;

    -- Consulta ACOTADA con data_scope = OWN, servida por ix_incidencia_mis_incidencias.
    SELECT COUNT(*) INTO v_propias FROM incidencia WHERE reported_by = v_sesion;
    IF v_propias <> 3 THEN
        RAISE_APPLICATION_ERROR(-20971, 'ORACULO AC-SEG-01: el listado acotado por reported_by devuelve ' || v_propias || ' incidencias en lugar de 3');
    END IF;

    -- El conjunto acotado y el conjunto ajeno tienen que ser disjuntos: ni una sola fila en comun.
    SELECT COUNT(*)
      INTO v_ajenas
      FROM incidencia
     WHERE reported_by = v_ajeno
       AND incident_id IN (SELECT incident_id FROM incidencia WHERE reported_by = v_sesion);
    IF v_ajenas <> 0 THEN
        RAISE_APPLICATION_ERROR(-20972, 'ORACULO AC-SEG-01: el listado propio incluye ' || v_ajenas || ' incidencias ajenas');
    END IF;

    -- REQ-158: orden por defecto created_at DESC, incident_id DESC.
    SELECT incident_id
      INTO v_primera
      FROM (SELECT incident_id
              FROM incidencia
             WHERE reported_by = v_sesion
             ORDER BY created_at DESC, incident_id DESC)
     WHERE ROWNUM = 1;

    SELECT MAX(incident_id) INTO v_maxima FROM incidencia WHERE reported_by = v_sesion;

    IF v_primera <> v_maxima THEN
        RAISE_APPLICATION_ERROR(-20973, 'ORACULO REQ-158: el orden created_at DESC, incident_id DESC no es determinista');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
